func TestRoundTrip(t *testing.T) {
	ctx := NewContext(context.Background(), "ada")
	got, ok := FromContext(ctx)
	if !ok || got != "ada" {
		t.Errorf("FromContext = %q, %v, want \"ada\", true", got, ok)
