func TestMissingValue(t *testing.T) {
	got, ok := FromContext(context.Background())
	if ok || got != "" {
		t.Errorf("FromContext on a context with no user = %q, %v, want \"\", false", got, ok)
	}
}

func TestEmptyIDIsStillPresent(t *testing.T) {
	got, ok := FromContext(NewContext(context.Background(), ""))
	if !ok || got != "" {
		t.Errorf("FromContext after storing an empty id = %q, %v, want \"\", true", got, ok)
	}
}

func TestNewContextLeavesParentAlone(t *testing.T) {
	parent := context.Background()
	NewContext(parent, "ada")
	if _, ok := FromContext(parent); ok {
		t.Error("storing a user must not change the context that was passed in")
	}
}

func TestDerivedContextSeesValue(t *testing.T) {
	child, cancel := context.WithCancel(NewContext(context.Background(), "ada"))
	defer cancel()
	got, ok := FromContext(child)
	if !ok || got != "ada" {
		t.Errorf("FromContext on a derived context = %q, %v, want \"ada\", true", got, ok)
	}
}

func TestInnerValueShadowsOuter(t *testing.T) {
	outer := NewContext(context.Background(), "ada")
	inner := NewContext(outer, "grace")
	if got, _ := FromContext(inner); got != "grace" {
		t.Errorf("inner context holds %q, want \"grace\"", got)
	}
	if got, _ := FromContext(outer); got != "ada" {
		t.Errorf("outer context holds %q, want \"ada\"", got)
	}
}

func TestKeyCannotCollideWithOtherPackages(t *testing.T) {
	ctx := NewContext(context.Background(), "ada")
	for _, key := range []any{"userID", "userid", "user", "user_id", "id", "key", 0, 1, struct{}{}} {
		if got := ctx.Value(key); got != nil {
			t.Errorf("another package looking up %#v found %v: use a key of your own private type", key, got)
		}
	}

	foreign := context.WithValue(context.Background(), "userID", "mallory")
	if got, ok := FromContext(foreign); ok {
		t.Errorf("FromContext found %q, which another package stored under its own key", got)
	}
}

