package exercise

import (
	"context"
	"errors"
	"sync/atomic"
	"testing"
	"time"
)

type ctxKey struct{}

func call(t *testing.T, parent context.Context, timeout, minimum time.Duration, work func(context.Context) string) (string, error) {
	t.Helper()
	type outcome struct {
		value string
		err   error
	}
	done := make(chan outcome, 1)
	go func() {
		value, err := RunWithin(parent, timeout, minimum, work)
		done <- outcome{value, err}
	}()
	select {
	case o := <-done:
		return o.value, o.err
	case <-time.After(2 * time.Second):
		t.Fatal("RunWithin is still waiting for work that will not finish: it should have given up")
		return "", nil
	}
}

func blockedWork(t *testing.T) func(context.Context) string {
	release := make(chan struct{})
	t.Cleanup(func() { close(release) })
	return func(context.Context) string {
		<-release
		return "too late"
	}
}

func TestWorkFinishesInTime(t *testing.T) {
	got, err := call(t, context.Background(), time.Second, 0, func(context.Context) string { return "done" })
	if err != nil {
		t.Fatalf("did not expect an error, got %v", err)
	}
	if got != "done" {
		t.Errorf("got %q, want \"done\"", got)
	}
}

func TestWorkContextComesFromParentAndIsReleased(t *testing.T) {
	parent := context.WithValue(context.Background(), ctxKey{}, "from parent")
	seen := make(chan context.Context, 1)
	_, err := call(t, parent, time.Second, 0, func(ctx context.Context) string {
		seen <- ctx
		return "done"
	})
	if err != nil {
		t.Fatalf("did not expect an error, got %v", err)
	}
	ctx := <-seen
	if _, ok := ctx.Deadline(); !ok {
		t.Error("the context handed to work has no deadline")
	}
	if ctx.Value(ctxKey{}) != "from parent" {
		t.Error("the context handed to work was not derived from the parent")
	}
	if !errors.Is(ctx.Err(), context.Canceled) {
		t.Errorf("after returning, the derived context reports %v: its resources were not released", ctx.Err())
	}
}

func TestTimesOut(t *testing.T) {
	got, err := call(t, context.Background(), 20*time.Millisecond, 0, blockedWork(t))
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Errorf("err = %v, want the deadline-exceeded error", err)
	}
	if got != "" {
		t.Errorf("got %q, want an empty result", got)
	}
}

func TestParentCancelled(t *testing.T) {
	parent, cancel := context.WithCancel(context.Background())
	defer cancel()
	time.AfterFunc(20*time.Millisecond, cancel)
	got, err := call(t, parent, time.Minute, 0, blockedWork(t))
	if !errors.Is(err, context.Canceled) {
		t.Errorf("err = %v, want the cancelled error", err)
	}
	if got != "" {
		t.Errorf("got %q, want an empty result", got)
	}
}

func TestParentDeadlineWinsOverLongerTimeout(t *testing.T) {
	parent, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	_, err := call(t, parent, time.Hour, 0, blockedWork(t))
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Errorf("err = %v, want the deadline-exceeded error", err)
	}
}

func TestSkipsWorkWhenTimeoutIsTooShort(t *testing.T) {
	var started atomic.Bool
	got, err := call(t, context.Background(), 50*time.Millisecond, time.Hour, func(context.Context) string {
		started.Store(true)
		return "done"
	})
	if !errors.Is(err, ErrNotEnoughTime) {
		t.Errorf("err = %v, want ErrNotEnoughTime", err)
	}
	if got != "" {
		t.Errorf("got %q, want an empty result", got)
	}
	time.Sleep(20 * time.Millisecond)
	if started.Load() {
		t.Error("work was started even though there was not enough time")
	}
}

func TestSkipsWorkWhenParentDeadlineIsTooClose(t *testing.T) {
	parent, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()
	var started atomic.Bool
	_, err := call(t, parent, time.Hour, time.Minute, func(context.Context) string {
		started.Store(true)
		return "done"
	})
	if !errors.Is(err, ErrNotEnoughTime) {
		t.Errorf("err = %v, want ErrNotEnoughTime: the parent's deadline leaves too little time", err)
	}
	time.Sleep(20 * time.Millisecond)
	if started.Load() {
		t.Error("work was started even though there was not enough time")
	}
}

