package exercise

import (
	"context"
	"errors"
	"time"
)

var ErrNotEnoughTime = errors.New("not enough time")

func RunWithin(parent context.Context, timeout, minimum time.Duration, work func(context.Context) string) (string, error) {
	ctx, cancel := context.WithTimeout(parent, timeout)
	defer cancel()

	if deadline, ok := ctx.Deadline(); ok && time.Until(deadline) < minimum {
		return "", ErrNotEnoughTime
	}

	result := make(chan string, 1)
	go func() {
		result <- work(ctx)
	}()

	select {
	case value := <-result:
		return value, nil
	case <-ctx.Done():
		return "", ctx.Err()
	}
}

