package exercise

import (
	"context"
	"errors"
	"runtime"
	"testing"
	"time"
)

type worker = func(context.Context) (string, error)

func call(t *testing.T, parent context.Context, workers []worker) (string, error) {
	t.Helper()
	type outcome struct {
		value string
		err   error
	}
	done := make(chan outcome, 1)
	go func() {
		value, err := FirstResult(parent, workers)
		done <- outcome{value, err}
	}()
	select {
	case o := <-done:
		return o.value, o.err
	case <-time.After(2 * time.Second):
		t.Fatal("FirstResult did not return: the workers must run at the same time, and it must not wait for more than it needs")
		return "", nil
	}
}

func TestReturnsTheQuickestSuccess(t *testing.T) {
	got, err := call(t, context.Background(), []worker{
		func(ctx context.Context) (string, error) {
			<-ctx.Done()
			return "slow", nil
		},
		func(context.Context) (string, error) { return "fast", nil },
	})
	if err != nil {
		t.Fatalf("did not expect an error, got %v", err)
	}
	if got != "fast" {
		t.Errorf("got %q, want \"fast\"", got)
	}
}

func TestWorkersRunAtTheSameTime(t *testing.T) {
	bothStarted := make(chan struct{})
	got, err := call(t, context.Background(), []worker{
		func(ctx context.Context) (string, error) {
			select {
			case <-bothStarted:
				return "first", nil
			case <-ctx.Done():
				return "", ctx.Err()
			}
		},
		func(context.Context) (string, error) {
			close(bothStarted)
			<-make(chan struct{})
			return "", nil
		},
	})
	if err != nil || got != "first" {
		t.Errorf("got %q, %v, want \"first\", no error", got, err)
	}
}

func TestLosersAreToldToStop(t *testing.T) {
	stopped := make(chan struct{}, 2)
	loser := func(ctx context.Context) (string, error) {
		<-ctx.Done()
		stopped <- struct{}{}
		return "", ctx.Err()
	}
	_, err := call(t, context.Background(), []worker{
		loser,
		func(context.Context) (string, error) { return "fast", nil },
		loser,
	})
	if err != nil {
		t.Fatalf("did not expect an error, got %v", err)
	}
	for i := 0; i < 2; i++ {
		select {
		case <-stopped:
		case <-time.After(time.Second):
			t.Fatal("a losing worker was never told to stop")
		}
	}
}

func TestFailureDoesNotEndTheRace(t *testing.T) {
	got, err := call(t, context.Background(), []worker{
		func(context.Context) (string, error) { return "", errors.New("broken") },
		func(context.Context) (string, error) {
			time.Sleep(20 * time.Millisecond)
			return "survivor", nil
		},
	})
	if err != nil || got != "survivor" {
		t.Errorf("got %q, %v, want \"survivor\", no error", got, err)
	}
}

func TestReturnsLastErrorWhenAllFail(t *testing.T) {
	early, late := errors.New("early"), errors.New("late")
	got, err := call(t, context.Background(), []worker{
		func(context.Context) (string, error) {
			time.Sleep(30 * time.Millisecond)
			return "", late
		},
		func(context.Context) (string, error) { return "", early },
	})
	if !errors.Is(err, late) {
		t.Errorf("err = %v, want the error of the worker that failed last", err)
	}
	if got != "" {
		t.Errorf("got %q, want an empty result", got)
	}
}

func TestNoWorkersIsAnError(t *testing.T) {
	if _, err := call(t, context.Background(), nil); err == nil {
		t.Error("expected an error when there are no workers")
	}
}

func TestParentCancelledWhileWorkersIgnoreIt(t *testing.T) {
	release := make(chan struct{})
	defer close(release)
	parent, cancel := context.WithCancel(context.Background())
	defer cancel()
	time.AfterFunc(20*time.Millisecond, cancel)
	got, err := call(t, parent, []worker{
		func(context.Context) (string, error) {
			<-release
			return "too late", nil
		},
	})
	if !errors.Is(err, context.Canceled) {
		t.Errorf("err = %v, want the cancelled error", err)
	}
	if got != "" {
		t.Errorf("got %q, want an empty result", got)
	}
}

func TestLosersDoNotLeak(t *testing.T) {
	before := runtime.NumGoroutine()
	_, err := call(t, context.Background(), []worker{
		func(context.Context) (string, error) { return "fast", nil },
		func(context.Context) (string, error) {
			time.Sleep(10 * time.Millisecond)
			return "slow", nil
		},
		func(context.Context) (string, error) {
			time.Sleep(10 * time.Millisecond)
			return "", errors.New("slow failure")
		},
	})
	if err != nil {
		t.Fatalf("did not expect an error, got %v", err)
	}
	limit := time.Now().Add(time.Second)
	for runtime.NumGoroutine() > before {
		if time.Now().After(limit) {
			t.Fatalf("%d goroutines before, %d after: a worker that finished late is stuck reporting its result", before, runtime.NumGoroutine())
		}
		time.Sleep(5 * time.Millisecond)
	}
}

