package exercise

import (
	"context"
	"errors"
)

func FirstResult(parent context.Context, workers []func(context.Context) (string, error)) (string, error) {
	ctx, cancel := context.WithCancel(parent)
	defer cancel()

	type result struct {
		value string
		err   error
	}
	results := make(chan result, len(workers))
	for _, work := range workers {
		go func(work func(context.Context) (string, error)) {
			value, err := work(ctx)
			results <- result{value, err}
		}(work)
	}

	lastErr := errors.New("no workers")
	for range workers {
		select {
		case r := <-results:
			if r.err == nil {
				return r.value, nil
			}
			lastErr = r.err
		case <-ctx.Done():
			return "", ctx.Err()
		}
	}
	return "", lastErr
}

