package exercise

import (
	"context"
	"errors"
	"io"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"
	"time"
)

type handleFunc = func(*http.Response, error) error

func call(t *testing.T, ctx context.Context, req *http.Request, f handleFunc) error {
	t.Helper()
	done := make(chan error, 1)
	go func() { done <- HTTPDo(ctx, req, f) }()
	select {
	case err := <-done:
		return err
	case <-time.After(2 * time.Second):
		t.Fatal("HTTPDo did not return: is the request tied to the context?")
		return nil
	}
}

func newRequest(t *testing.T, url string) *http.Request {
	t.Helper()
	req, err := http.NewRequest(http.MethodGet, url, nil)
	if err != nil {
		t.Fatal(err)
	}
	return req
}

func helloServer(t *testing.T) *httptest.Server {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		io.WriteString(w, "hello")
	}))
	t.Cleanup(srv.Close)
	return srv
}

func stuckServer(t *testing.T) *httptest.Server {
	release := make(chan struct{})
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		select {
		case <-release:
		case <-r.Context().Done():
		}
	}))
	t.Cleanup(srv.Close)
	t.Cleanup(func() { close(release) })
	return srv
}

func TestCallbackReadsTheResponse(t *testing.T) {
	srv := helloServer(t)
	var body string
	err := call(t, context.Background(), newRequest(t, srv.URL), func(resp *http.Response, err error) error {
		if err != nil {
			return err
		}
		defer resp.Body.Close()
		b, err := io.ReadAll(resp.Body)
		body = string(b)
		return err
	})
	if err != nil {
		t.Fatalf("did not expect an error, got %v", err)
	}
	if body != "hello" {
		t.Errorf("the callback read %q, want \"hello\"", body)
	}
}

func TestReturnsTheCallbacksError(t *testing.T) {
	srv := helloServer(t)
	boom := errors.New("boom")
	err := call(t, context.Background(), newRequest(t, srv.URL), func(resp *http.Response, err error) error {
		if err == nil {
			resp.Body.Close()
		}
		return boom
	})
	if !errors.Is(err, boom) {
		t.Errorf("err = %v, want the callback's error", err)
	}
}

func TestCallbackSeesRequestFailure(t *testing.T) {
	srv := helloServer(t)
	url := srv.URL
	srv.Close()
	var got error
	err := call(t, context.Background(), newRequest(t, url), func(resp *http.Response, err error) error {
		got = err
		return err
	})
	if got == nil {
		t.Error("the callback should have received the request's error")
	}
	if err == nil {
		t.Error("expected the callback's error back")
	}
}

func TestCancelAbortsTheRequest(t *testing.T) {
	srv := stuckServer(t)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	time.AfterFunc(20*time.Millisecond, cancel)

	var callbackErr atomic.Value
	err := call(t, ctx, newRequest(t, srv.URL), func(resp *http.Response, err error) error {
		if err == nil {
			resp.Body.Close()
			return nil
		}
		callbackErr.Store(err)
		return err
	})
	if !errors.Is(err, context.Canceled) {
		t.Errorf("err = %v, want the cancelled error", err)
	}
	got, _ := callbackErr.Load().(error)
	if !errors.Is(got, context.Canceled) {
		t.Errorf("the callback received %v: cancelling should abort the request itself", got)
	}
}

func TestTimeoutReportsDeadlineExceeded(t *testing.T) {
	srv := stuckServer(t)
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	err := call(t, ctx, newRequest(t, srv.URL), func(resp *http.Response, err error) error {
		if err == nil {
			resp.Body.Close()
		}
		return err
	})
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Errorf("err = %v, want the deadline-exceeded error", err)
	}
}

func TestCancelWaitsForCallbackAndReturnsContextError(t *testing.T) {
	srv := helloServer(t)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	var finished atomic.Bool
	err := call(t, ctx, newRequest(t, srv.URL), func(resp *http.Response, err error) error {
		if err == nil {
			resp.Body.Close()
		}
		cancel()
		time.Sleep(50 * time.Millisecond)
		finished.Store(true)
		return errors.New("from the callback")
	})
	if !finished.Load() {
		t.Error("HTTPDo returned while the callback was still running")
	}
	if !errors.Is(err, context.Canceled) {
		t.Errorf("err = %v, want the cancelled error rather than the callback's", err)
	}
}

